-- Isolated database only, with all fixtures and changes rolled back.
begin;
\ir progression_fixture.sql
create function pg_temp.sr(p jsonb default '{}')returns jsonb language sql as $$select public.dcc_safe_room_snapshot(current_setting('dcc_test.pg_id')::uuid,p)$$;
create function pg_temp.sr_act(op text,p jsonb default '{}')returns void language plpgsql as $$begin perform public.dcc_safe_room_action(current_setting('dcc_test.pg_id')::uuid,op,p);end$$;
create function pg_temp.sr_box()returns jsonb language sql as $$select pg_temp.sr('{"hideClaimed":false}')->'boxes'->0$$;
create function pg_temp.sr_item(name text)returns jsonb language sql as $$select jsonb_build_object('name',name,'kind','gear','quantity',1,'notes','Reviewed reward','gearSlot','none','effect','manual','bonuses','{"strength":0,"intelligence":0,"constitution":0,"dexterity":0,"charisma":0,"dr":0,"evade":0}'::jsonb)$$;
create function pg_temp.sr_award(locked boolean default false,existing boolean default false,source text default 'manual')returns jsonb language sql as $$select jsonb_build_object('requestId',gen_random_uuid(),'reviewed',true,'existing',existing,'source',source,
 'achievement',jsonb_build_object('title','Table Award','floor',3,'trigger','Protected the party','description','Congratulations. Teamwork has been discovered.','rewardText','Reviewed by the GM'),
 'box',jsonb_build_object('tier','gold','name','Gold Adventurer Box','category','Adventurer','flavor','The lid unseals.','aiNote','Try not to lose these.','guideNote','Check the contents.','voteLocked',locked,'sourceAchievementId',null,'items',jsonb_build_array(pg_temp.sr_item('Rope'),pg_temp.sr_item('Torch'))))$$;
select set_config('dcc_test.sr_original',(select to_jsonb(c)::text from public.dcc_crawlers c where id=current_setting('dcc_test.pg_id')::uuid),true);
set local role authenticated;
select set_config('request.jwt.claim.sub','c1911111-1111-4111-8111-111111111111',true);
select pg_temp.pg_assert(pg_temp.sr()->>'unopened'='0' and pg_temp.sr()#>>'{access,allowed}'='false','New migration must not issue rewards or grant access.');
select set_config('dcc_test.sr_award',pg_temp.sr_award()::text,true);
select pg_temp.sr_act('award',current_setting('dcc_test.sr_award')::jsonb);
select pg_temp.sr_act('award',current_setting('dcc_test.sr_award')::jsonb);
select pg_temp.pg_assert(pg_temp.sr()->>'unopened'='1' and pg_temp.sr()->>'achievementCount'='1','A retry duplicated the linked achievement/box.');
select pg_temp.pg_assert(jsonb_array_length(pg_temp.sr_box()->'items')=2,'GM cannot review unopened contents.');
select set_config('dcc_test.sr_box',pg_temp.sr_box()->>'id',true);
select set_config('dcc_test.sr_aid',pg_temp.sr()#>>'{achievements,0,id}',true);
select set_config('dcc_test.sr_item',pg_temp.sr_box()#>>'{items,0,id}',true);
select set_config('dcc_test.sr_other_item',pg_temp.sr_box()#>>'{items,1,id}',true);
select pg_temp.pg_assert((select to_jsonb(c) from public.dcc_crawlers c where id=current_setting('dcc_test.pg_id')::uuid)=current_setting('dcc_test.sr_original')::jsonb,'Awarding rewrote the crawler or granted inventory early.');
select set_config('request.jwt.claim.sub','c1933333-3333-4333-8333-333333333333',true);
select pg_temp.pg_error('select pg_temp.sr()','42501');
select pg_temp.pg_assert(not exists(select 1 from public.dcc_loot_boxes) and not exists(select 1 from public.dcc_loot_box_items) and not exists(select 1 from public.dcc_achievements),'Another player can read reward data.');
select set_config('request.jwt.claim.sub','c1922222-2222-4222-8222-222222222222',true);
select pg_temp.pg_assert(pg_temp.sr_box()->'items'='null' and not exists(select 1 from public.dcc_loot_box_items),'Sealed contents leak through snapshots or direct table reads.');
select pg_temp.pg_assert(public.dcc_hud_snapshot(current_setting('dcc_test.pg_game')::uuid,3)->>'unopenedBoxes'='1','HUD unopened badge missing.');
select pg_temp.pg_error('select pg_temp.sr_act(''award'',pg_temp.sr_award())','42501');
select pg_temp.pg_error('select pg_temp.sr_act(''access'',''{"floor":3,"version":null,"allowed":true}'')','42501');
select pg_temp.pg_error('update public.dcc_loot_box_items set claimed_at=now()','42501');
select pg_temp.pg_error('select pg_temp.sr_act(''open'',jsonb_build_object(''boxId'',current_setting(''dcc_test.sr_box''),''version'',pg_temp.sr_box()->>''version''))','22023');
select pg_temp.sr_act('read',jsonb_build_object('achievementId',current_setting('dcc_test.sr_aid')));
select pg_temp.pg_assert(pg_temp.sr()->>'unreadAchievements'='0','Achievement read acknowledgement failed.');
select set_config('request.jwt.claim.sub','c1911111-1111-4111-8111-111111111111',true);
select pg_temp.pg_assert(pg_temp.sr()->>'unreadAchievements'='1','Reading changed the GM account read state.');
select pg_temp.sr_act('access','{"floor":3,"version":null,"allowed":true}');
select pg_temp.pg_error('select pg_temp.sr_act(''access'',''{"floor":3,"version":null,"allowed":false}'')','40001');
select set_config('request.jwt.claim.sub','c1922222-2222-4222-8222-222222222222',true);
select set_config('dcc_test.sr_sealed_version',pg_temp.sr_box()->>'version',true);
select pg_temp.sr_act('open',jsonb_build_object('boxId',current_setting('dcc_test.sr_box'),'version',current_setting('dcc_test.sr_sealed_version')));
select pg_temp.sr_act('open',jsonb_build_object('boxId',current_setting('dcc_test.sr_box'),'version',current_setting('dcc_test.sr_sealed_version')));
select pg_temp.pg_assert(jsonb_array_length(pg_temp.sr_box()->'items')=2 and (select count(*)=2 from public.dcc_loot_box_items),'Opened contents did not reveal.');
select pg_temp.pg_assert((select to_jsonb(c) from public.dcc_crawlers c where id=current_setting('dcc_test.pg_id')::uuid)=current_setting('dcc_test.sr_original')::jsonb,'Opening changed inventory/resources or crawler version.');
select pg_temp.pg_error('select pg_temp.sr_act(''claim'',jsonb_build_object(''boxId'',current_setting(''dcc_test.sr_box''),''version'',pg_temp.sr_box()->>''version'',''crawlerVersion'',''e2333333-3333-4333-8333-333333333333'',''itemId'',null))','40001');
select set_config('dcc_test.sr_first_claim',jsonb_build_object('boxId',current_setting('dcc_test.sr_box'),'version',pg_temp.sr_box()->>'version','crawlerVersion',pg_temp.sr()->>'crawlerVersion','itemId',current_setting('dcc_test.sr_item'))::text,true);
select pg_temp.sr_act('claim',current_setting('dcc_test.sr_first_claim')::jsonb);
select pg_temp.sr_act('claim',current_setting('dcc_test.sr_first_claim')::jsonb);
select pg_temp.pg_assert((select count(*)=1 from public.dcc_crawlers c,jsonb_array_elements(c.inventory) i where c.id=current_setting('dcc_test.pg_id')::uuid and i->>'id'=current_setting('dcc_test.sr_item')),'One-item claim duplicated or failed.');
select pg_temp.pg_error('select pg_temp.sr_act(''claim'',(current_setting(''dcc_test.sr_first_claim'')::jsonb)||''{"itemId":null}'')','40001');
select pg_temp.sr_act('claim',jsonb_build_object('boxId',current_setting('dcc_test.sr_box'),'version',pg_temp.sr_box()->>'version','crawlerVersion',pg_temp.sr()->>'crawlerVersion','itemId',null));
select pg_temp.pg_assert(pg_temp.sr_box()->>'status'='claimed' and pg_temp.sr()->>'unopened'='0','Claim All did not finish the box.');
select pg_temp.pg_assert((select (to_jsonb(c)-'inventory'-'version')=(current_setting('dcc_test.sr_original')::jsonb-'inventory'-'version') from public.dcc_crawlers c where id=current_setting('dcc_test.pg_id')::uuid),'Claiming changed stats, points, Mana, health or original selection.');
-- Deleting/consuming a claimed item never makes its receipt claimable again.
reset role;
update public.dcc_crawlers set inventory=(select coalesce(jsonb_agg(i),'[]') from jsonb_array_elements(inventory) i where i->>'id'<>current_setting('dcc_test.sr_item')),version=gen_random_uuid() where id=current_setting('dcc_test.pg_id')::uuid;
set local role authenticated;
select pg_temp.sr_act('claim',current_setting('dcc_test.sr_first_claim')::jsonb);
select pg_temp.pg_assert(not exists(select 1 from public.dcc_crawlers c,jsonb_array_elements(c.inventory) i where c.id=current_setting('dcc_test.pg_id')::uuid and i->>'id'=current_setting('dcc_test.sr_item')),'Removed claimed loot was granted again.');
select set_config('request.jwt.claim.sub','c1911111-1111-4111-8111-111111111111',true);
select pg_temp.sr_act('award',pg_temp.sr_award(true));
select pg_temp.pg_error('select pg_temp.sr_act(''open'',jsonb_build_object(''boxId'',pg_temp.sr_box()->>''id'',''version'',pg_temp.sr_box()->>''version''))','22023');
select set_config('request.jwt.claim.sub','c1922222-2222-4222-8222-222222222222',true);
select pg_temp.pg_error('select pg_temp.sr_act(''unlock'',jsonb_build_object(''boxId'',pg_temp.sr_box()->>''id'',''version'',pg_temp.sr_box()->>''version'',''confirmed'',true))','42501');
select set_config('request.jwt.claim.sub','c1911111-1111-4111-8111-111111111111',true);
select pg_temp.sr_act('unlock',jsonb_build_object('boxId',pg_temp.sr_box()->>'id','version',pg_temp.sr_box()->>'version','confirmed',true));
select pg_temp.sr_act('open',jsonb_build_object('boxId',pg_temp.sr_box()->>'id','version',pg_temp.sr_box()->>'version'));
select set_config('dcc_test.sr_before_legacy',(select to_jsonb(c)::text from public.dcc_crawlers c where id=current_setting('dcc_test.pg_id')::uuid),true);
select pg_temp.sr_act('award',pg_temp.sr_award(false,true));
select pg_temp.pg_assert(pg_temp.sr_box()->>'status'='claimed' and pg_temp.sr_box()->>'existing'='true','Historical reward was not recorded as fulfilled.');
select pg_temp.pg_assert((select to_jsonb(c) from public.dcc_crawlers c where id=current_setting('dcc_test.pg_id')::uuid)=current_setting('dcc_test.sr_before_legacy')::jsonb,'Recording an existing reward modified the crawler or regranted items.');
select pg_temp.pg_error('select pg_temp.sr_act(''award'',pg_temp.sr_award(false,false,''earth-incentive''))','22023');
select public.dcc_progression_action(current_setting('dcc_test.pg_id')::uuid,(select version from public.dcc_crawlers where id=current_setting('dcc_test.pg_id')::uuid),'reward','{"decision":"issue-once","reason":"Reviewed existing incentive","confirmed":true}');
select pg_temp.sr_act('award',pg_temp.sr_award(false,false,'earth-incentive'));
select pg_temp.pg_assert(pg_temp.sr()->>'incentive'='issued','Single incentive ledger was not consumed.');
select pg_temp.pg_error('select pg_temp.sr_act(''award'',pg_temp.sr_award(false,false,''earth-incentive''))','23505');
-- Leaving and returning to the same floor must not resurrect saferoom permission.
select public.dcc_sheet_action(current_setting('dcc_test.pg_id')::uuid,(select version from public.dcc_crawlers where id=current_setting('dcc_test.pg_id')::uuid),'floor','{"value":4}');
select public.dcc_sheet_action(current_setting('dcc_test.pg_id')::uuid,(select version from public.dcc_crawlers where id=current_setting('dcc_test.pg_id')::uuid),'floor','{"value":3}');
select pg_temp.pg_assert(pg_temp.sr()#>>'{access,allowed}'='false','Saferoom access survived a floor change.');
-- Capacity failure is all-or-nothing; a one-item claim can use the last free entry.
select pg_temp.sr_act('access',jsonb_build_object('floor',3,'version',pg_temp.sr()#>>'{access,version}','allowed',true));
select pg_temp.sr_act('open',jsonb_build_object('boxId',pg_temp.sr_box()->>'id','version',pg_temp.sr_box()->>'version'));
reset role;
update public.dcc_crawlers set inventory=(select jsonb_agg(pg_temp.sr_item('Stored entry')||jsonb_build_object('id',gen_random_uuid(),'location','stored')) from generate_series(1,200)),version=gen_random_uuid() where id=current_setting('dcc_test.pg_id')::uuid;
select set_config('dcc_test.sr_full',(select to_jsonb(c)::text from public.dcc_crawlers c where id=current_setting('dcc_test.pg_id')::uuid),true);
set local role authenticated;
select pg_temp.pg_error('select pg_temp.sr_act(''claim'',jsonb_build_object(''boxId'',pg_temp.sr_box()->>''id'',''version'',pg_temp.sr_box()->>''version'',''crawlerVersion'',pg_temp.sr()->>''crawlerVersion'',''itemId'',null))','54000');
select pg_temp.pg_assert((select to_jsonb(c) from public.dcc_crawlers c where id=current_setting('dcc_test.pg_id')::uuid)=current_setting('dcc_test.sr_full')::jsonb and pg_temp.sr_box()->>'status'='opened','A failed Claim All partially granted or changed receipts.');
reset role;
update public.dcc_crawlers set inventory=inventory-199,version=gen_random_uuid() where id=current_setting('dcc_test.pg_id')::uuid;
set local role authenticated;
select pg_temp.sr_act('claim',jsonb_build_object('boxId',pg_temp.sr_box()->>'id','version',pg_temp.sr_box()->>'version','crawlerVersion',pg_temp.sr()->>'crawlerVersion','itemId',pg_temp.sr_box()#>>'{items,0,id}'));
select pg_temp.pg_assert((select jsonb_array_length(inventory)=200 from public.dcc_crawlers where id=current_setting('dcc_test.pg_id')::uuid),'Single-item claim did not use the final free inventory entry.');
select pg_temp.pg_error('select dcc_private.reward_box_json(null)','42501');
select pg_temp.pg_error('select dcc_private.hud_before_rewards(null,null,null)','42501');
select 'PASS: private Safe Room rewards, persistent receipts, atomic inventory claims, roles, legacy reconciliation and access expiry';
rollback;
